SOURCE tests/procedures/support/fixture.sql;
SET @p3_phone=CONCAT('7',LPAD(MOD(UUID_SHORT(),1000000000),9,'0'));
CALL bank_lab.sp_expect_ok(DATABASE(),'register success','CALL {db}.sp_register_customer(''Synthetic'',''1990-01-01'',NULL,CONCAT(''valid.'',@p3_tag,''@example.invalid''),@p3_phone,''Synthetic address'',CONCAT(''SYN3-'',LEFT(@p3_tag,24)),''PAN'',@p3_new)');
SET @p3_ok=(SELECT COUNT(*)=1 FROM Customers WHERE customer_id=@p3_new AND kyc_status='Pending' AND is_active=1 AND gender IS NULL);
CALL bank_lab.sp_assert_true(DATABASE(),'register defaults',@p3_ok,'Expected procedure contract');
CALL bank_lab.sp_expect_error(DATABASE(),'register empty name','CALL {db}.sp_register_customer('''',''1990-01-01'',NULL,CONCAT(''valid.'',@p3_tag,''@example.invalid''),@p3_phone,''Synthetic address'',CONCAT(''SYN3-'',LEFT(@p3_tag,24)),''PAN'',@p3_new)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'register NULL name','CALL {db}.sp_register_customer(NULL,''1990-01-01'',NULL,CONCAT(''valid.'',@p3_tag,''@example.invalid''),@p3_phone,''Synthetic address'',CONCAT(''SYN3-'',LEFT(@p3_tag,24)),''PAN'',@p3_new)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'register future dob','CALL {db}.sp_register_customer(''Synthetic'',DATE_ADD(CURDATE(),INTERVAL 1 DAY),NULL,CONCAT(''valid.'',@p3_tag,''@example.invalid''),@p3_phone,''Synthetic address'',CONCAT(''SYN3-'',LEFT(@p3_tag,24)),''PAN'',@p3_new)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'register NULL dob','CALL {db}.sp_register_customer(''Synthetic'',NULL,NULL,CONCAT(''valid.'',@p3_tag,''@example.invalid''),@p3_phone,''Synthetic address'',CONCAT(''SYN3-'',LEFT(@p3_tag,24)),''PAN'',@p3_new)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'register bad email','CALL {db}.sp_register_customer(''Synthetic'',''1990-01-01'',NULL,''bad'',@p3_phone,''Synthetic address'',CONCAT(''SYN3-'',LEFT(@p3_tag,24)),''PAN'',@p3_new)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'register NULL email','CALL {db}.sp_register_customer(''Synthetic'',''1990-01-01'',NULL,NULL,@p3_phone,''Synthetic address'',CONCAT(''SYN3-'',LEFT(@p3_tag,24)),''PAN'',@p3_new)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'register bad phone','CALL {db}.sp_register_customer(''Synthetic'',''1990-01-01'',NULL,CONCAT(''valid.'',@p3_tag,''@example.invalid''),''abc'',''Synthetic address'',CONCAT(''SYN3-'',LEFT(@p3_tag,24)),''PAN'',@p3_new)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'register empty address','CALL {db}.sp_register_customer(''Synthetic'',''1990-01-01'',NULL,CONCAT(''valid.'',@p3_tag,''@example.invalid''),@p3_phone,'''',CONCAT(''SYN3-'',LEFT(@p3_tag,24)),''PAN'',@p3_new)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'register empty proof','CALL {db}.sp_register_customer(''Synthetic'',''1990-01-01'',NULL,CONCAT(''valid.'',@p3_tag,''@example.invalid''),@p3_phone,''Synthetic address'','''',''PAN'',@p3_new)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'register bad proof type','CALL {db}.sp_register_customer(''Synthetic'',''1990-01-01'',NULL,CONCAT(''valid.'',@p3_tag,''@example.invalid''),@p3_phone,''Synthetic address'',CONCAT(''SYN3-'',LEFT(@p3_tag,24)),''Other'',@p3_new)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'register NULL proof type','CALL {db}.sp_register_customer(''Synthetic'',''1990-01-01'',NULL,CONCAT(''valid.'',@p3_tag,''@example.invalid''),@p3_phone,''Synthetic address'',CONCAT(''SYN3-'',LEFT(@p3_tag,24)),NULL,@p3_new)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'register duplicate email','CALL {db}.sp_register_customer(''Synthetic'',''1990-01-01'',NULL,CONCAT(''valid.'',@p3_tag,''@example.invalid''),CONCAT(''7'',LPAD(MOD(UUID_SHORT(),1000000000),9,''0'')),''Synthetic address'',CONCAT(''SYN4-'',LEFT(@p3_tag,24)),''PAN'',@p3_new)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'register duplicate phone','CALL {db}.sp_register_customer(''Synthetic'',''1990-01-01'',NULL,CONCAT(''phone.'',@p3_tag,''@example.invalid''),@p3_phone,''Synthetic address'',CONCAT(''SYN5-'',LEFT(@p3_tag,24)),''PAN'',@p3_new)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'register duplicate proof','CALL {db}.sp_register_customer(''Synthetic'',''1990-01-01'',NULL,CONCAT(''proof.'',@p3_tag,''@example.invalid''),CONCAT(''7'',LPAD(MOD(UUID_SHORT(),1000000000),9,''0'')),''Synthetic address'',CONCAT(''SYN3-'',LEFT(@p3_tag,24)),''PAN'',@p3_new)',5018);

